mapper.select:
SELECT * FROM ( SELECT n.notice_id, n.title, n.content, n.image_url, n.view_cnt, n.is_pinned, n.is_visible, n.created_id, n.created_date, n.updated_id, n.updated_date FROM tb_notice n WHERE n.is_visible = 'Y'
AND n.title LIKE '%' || #{keyword} || '%'
AND n.notice_id < #{lastNoticeId}
ORDER BY n.is_pinned DESC, n.notice_id DESC ) WHERE ROWNUM <= #{limit}
